<?php
// All fixtures live in the schema-cloning workflow harness's disposable database.
require_once dirname(__DIR__).'/api/sku_lib.php';installToolSkuStorage($db);
require_once dirname(__DIR__).'/includes/stock_lib.php';installStockHistory($db);
$a=expectApi('Register checkout Baso','tools.php','POST',['name'=>'Session Baso','category'=>'Cookware','quantity'=>8,'min_stock'=>1,'price'=>5]);
$b=expectApi('Register checkout Skillet','tools.php','POST',['name'=>'Session Cast Iron Skillet','category'=>'Cookware','quantity'=>8,'min_stock'=>1,'price'=>5]);
$body=['type'=>'borrow_batch','borrower_id'=>1,'due_date'=>date('Y-m-d',strtotime('+1 day')),'due_time'=>'17:30','request_token'=>'session_checkout_12345678','items'=>[['tool_code'=>$a['code'],'qty'=>2],['tool_code'=>$b['code'],'qty'=>2]]];
$saved=expectApi('Confirm two-tool checkout','transactions.php','POST',$body,true,'Staff');
$byCode=array_column($saved['items'],null,'tool_code');$first=$byCode[$a['code']]['id'];$second=$byCode[$b['code']]['id'];$number=$saved['txn_id'];
check(count(array_unique(array_column($saved['items'],'txn_id')))===1&&$saved['items'][0]['txn_id']===$number,'One public TXN ID covers both tool lines');
check((int)$db->query('SELECT COUNT(*) FROM borrow_sessions')->fetchColumn()===1&&row('transactions',$first)['borrow_session_id']===row('transactions',$second)['borrow_session_id'],'Both detail rows link to one persisted header');
check((int)row('tools',(int)$a['id'])['available']===6&&(int)row('tools',(int)$b['id'])['available']===6,'Each tool loses exactly its two borrowed units');
check((int)row('borrowers',1)['active_borrows']===1&&(int)row('borrowers',1)['total_borrows']===1,'Borrower counters count the checkout once');
$history=api('transactions.php','GET',[],'Staff',['type'=>'borrow','grouped'=>1,'search'=>$number]);
check($history['success']&&$history['total']===1&&count($history['data'][0]['items'])===2,'History shows one checkout with two expandable details');
$search=api('transactions.php','GET',[],'Staff',['type'=>'borrow','grouped'=>1,'search'=>$a['name'],'page'=>99,'per_page'=>1]);
check($search['total']===1&&$search['page']===1&&count($search['data'][0]['items'])===2,'Tool search keeps complete checkout and clamps pagination');
$report=expectApi('Transaction report for shared number','reports.php','GET',[],true,'Staff',['type'=>'transactions','search'=>$number]);
check($report['transaction_count']===1&&count($report['rows'])===1&&count($report['groups'][0]['items'])===2&&$report['line_total']===2,'Report groups one transaction while retaining both quantity lines');
$month=expectApi('Monthly checkout count','reports.php','GET',[],true,'Staff',['type'=>'monthly']);check($month['total_borrows']===1,'Monthly analytics count one checkout');
$dash=expectApi('Dashboard checkout count','dashboard.php','GET');check($dash['active_borrows']===1&&array_sum($dash['weekly_borrows'])===1,'Dashboard and weekly analytics count one checkout');
expectApi('Return only Baso, including one damaged unit','transactions.php','POST',['type'=>'return','borrow_txn_id'=>$first,'returnee_name'=>'Session fixture','request_token'=>'session_return_first_12345','items'=>['good'=>1,'damaged'=>1]],true,'Staff');
check(row('transactions',$first)['status']==='returned'&&row('transactions',$second)['status']==='active'&&(int)row('transactions',$second)['qty_returned']===0,'Returning one tool does not close or modify the other');
$history=api('transactions.php','GET',[],'Staff',['type'=>'borrow','grouped'=>1,'status'=>'active','search'=>$number]);
check($history['total']===1&&$history['data'][0]['status']==='active'&&(int)$history['data'][0]['qty_damaged']===1,'Partial checkout remains active and exposes damage on its own line');
$closed=api('transactions.php','GET',[],'Staff',['type'=>'borrow','grouped'=>1,'status'=>'returned','search'=>$number]);check($closed['total']===0,'Closed checkout filter excludes a partially returned session');
check((int)row('borrowers',1)['active_borrows']===1,'Partial return keeps one active checkout');
$case=expectApi('Report one Skillet missing','missing_tools.php','POST',['action'=>'report','borrow_txn_id'=>$second,'qty'=>1,'missing_date'=>date('Y-m-d'),'reason'=>'Session line missing','request_token'=>'session_missing_line_12345'],true,'Staff');
expectApi('Confirm missing Skillet line','missing_tools.php','POST',['action'=>'confirm','id'=>$case['id'],'qty'=>1,'notes'=>'Confirmed fixture']);
check((int)row('transactions',$second)['qty_missing']===1&&(int)row('transactions',$first)['qty_missing']===0,'Missing confirmation stays on the affected detail');
expectApi('Return last outstanding Skillet','transactions.php','POST',['type'=>'return','borrow_txn_id'=>$second,'returnee_name'=>'Session fixture','request_token'=>'session_return_second_123','items'=>['good'=>1]],true,'Staff');
$history=api('transactions.php','GET',[],'Staff',['type'=>'borrow','grouped'=>1,'search'=>$number]);check($history['data'][0]['status']==='returned'&&(int)$history['data'][0]['qty_missing']===1&&(int)row('borrowers',1)['active_borrows']===0,'All details accounted for close checkout while missing accountability remains');
$beforeA=row('tools',(int)$a['id']);$beforeB=row('tools',(int)$b['id']);
$retry=expectApi('Retry original confirmation','transactions.php','POST',$body,true,'Staff');
check($retry['duplicate']&&$retry['txn_id']===$number&&$retry['items']===$saved['items']&&row('tools',(int)$a['id'])===$beforeA&&row('tools',(int)$b['id'])===$beforeB,'Retry returns the same header and details without stock adjustment');
$invalid=$body;$invalid['items'][0]['qty']=3;expectApi('Used checkout token rejects changed payload','transactions.php','POST',$invalid,false,'Staff');
$bad=$body;$bad['request_token']='session_bad_stock_123456';$bad['items'][1]['qty']=999;expectApi('Any invalid line rejects entire checkout','transactions.php','POST',$bad,false,'Staff');
check((int)$db->query('SELECT COUNT(*) FROM borrow_sessions')->fetchColumn()===1,'Failed validation leaves no header');
$db->exec('CREATE TRIGGER session_fail_second BEFORE INSERT ON transactions FOR EACH ROW BEGIN IF NEW.tool_id='.(int)$b['id']." AND NEW.type='borrow' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Second line fixture failure'; END IF; END");
$atomic=$body;$atomic['request_token']='session_atomic_failure_1234';
try{expectApi('Second detail insert failure rolls back checkout','transactions.php','POST',$atomic,false,'Staff');}finally{$db->exec('DROP TRIGGER session_fail_second');}
check((int)$db->query('SELECT COUNT(*) FROM borrow_sessions')->fetchColumn()===1&&row('tools',(int)$a['id'])===$beforeA&&row('tools',(int)$b['id'])===$beforeB,'Header, first detail and first stock deduction roll back together');
$atomicSaved=expectApi('Retry after rollback succeeds','transactions.php','POST',$atomic,true,'Staff');
$c=expectApi('Register last-unit fixture','tools.php','POST',['name'=>'Last Session Tool','category'=>'Cookware','quantity'=>1,'min_stock'=>1,'price'=>5]);
$raceBody=['type'=>'borrow_batch','borrower_id'=>1,'due_date'=>$body['due_date'],'due_time'=>'17:30','request_token'=>'session_race_one_1234567','items'=>[['tool_code'=>$c['code'],'qty'=>1]]];$other=$raceBody;$other['request_token']='session_race_two_1234567';
$headers=(int)$db->query('SELECT COUNT(*) FROM borrow_sessions')->fetchColumn();$race=concurrentApi('transactions.php','POST',[],2,[$raceBody,$other]);
check(count(array_filter($race,fn($r)=>$r['success']))===1&&(int)row('tools',(int)$c['id'])['available']===0&&(int)$db->query('SELECT COUNT(*) FROM borrow_sessions')->fetchColumn()===$headers+1,'Concurrent last-unit confirmations allow exactly one whole checkout');
$same=$body;$same['request_token']='session_duplicate_race_1234';$same['items'][0]['qty']=1;$same['items'][1]['qty']=1;
$headers=(int)$db->query('SELECT COUNT(*) FROM borrow_sessions')->fetchColumn();$race=concurrentApi('transactions.php','POST',$same);
check(count(array_filter($race,fn($r)=>$r['success']))===2&&count(array_filter($race,fn($r)=>!empty($r['data']['duplicate'])))===1&&(int)$db->query('SELECT COUNT(*) FROM borrow_sessions')->fetchColumn()===$headers+1,'Concurrent duplicate tokens produce one header and one set of detail lines');
$legacyTool=expectApi('Register legacy history fixture','tools.php','POST',['name'=>'Legacy Session Tool','category'=>'Cookware','quantity'=>2,'min_stock'=>1,'price'=>5]);
$db->prepare('UPDATE tools SET available=0 WHERE id=?')->execute([$legacyTool['id']]);
foreach(['OLD-SESSION-A','OLD-SESSION-B'] as $old)$db->prepare("INSERT INTO transactions(txn_id,type,tool_id,borrower_id,status,qty,due_date,created_at) VALUES(?,'borrow',?,1,'active',1,CURDATE(),'2025-01-01 10:00:00')")->execute([$old,$legacyTool['id']]);
$oldIds=$db->query("SELECT id,txn_id FROM transactions WHERE txn_id IN ('OLD-SESSION-A','OLD-SESSION-B') ORDER BY id")->fetchAll();
installBorrowSessions($db);installBorrowSessions($db);
$old=api('transactions.php','GET',[],'Staff',['type'=>'borrow','grouped'=>1,'search'=>'OLD-SESSION-']);check($old['total']===2&&array_column($db->query("SELECT id,txn_id FROM transactions WHERE txn_id IN ('OLD-SESSION-A','OLD-SESSION-B') ORDER BY id")->fetchAll(),'txn_id')===array_column($oldIds,'txn_id'),'Migration reruns preserve historical IDs and never merge borrower/timestamp coincidences');
expectApi('Legacy line is still returnable by numeric ID','transactions.php','POST',['type'=>'return','borrow_txn_id'=>$oldIds[0]['id'],'returnee_name'=>'Fixture','request_token'=>'session_legacy_return_123','items'=>['good'=>1]],true,'Staff');
invariant();
if(getenv('TOOLTRACK_BORROW_SESSION_BROWSER_TEST'))require __DIR__.'/borrow_session_browser_cases.php';
echo "PASSED: $checks borrow-session checks\n";
